#!/usr/bin/env python3
import pathlib
import re
import sys
import urllib.request

BUILDBOT = "https://buildbot.libretro.com/nightly/android/latest"

ABIS = {"arm64-v8a": "64", "armeabi-v7a": "32"}

ASSET = pathlib.Path(__file__).resolve().parent / "data/android_cores.txt"

HEADER = """\
# Cores with an Android build, from buildbot.libretro.com.
# Generated by scripts/android-cores.py. Do not hand-edit.
#
# Build input, not a shipped asset: CuratedCatalogueTest reads it to assert every curated core
# builds for both ABIs. The app does not consult it, because the catalogue is already only
# runnable cores.
#
# <core id> <abis>   64 = arm64-v8a, 32 = armeabi-v7a
"""


def fetch(abi):
    url = f"{BUILDBOT}/{abi}/"
    with urllib.request.urlopen(url, timeout=60) as response:
        page = response.read().decode("utf-8", "ignore")
    found = set(re.findall(r"([A-Za-z0-9_+\-]+_libretro)_android\.so\.zip", page))
    if not found:
        sys.exit(f"no cores parsed from {url}: the index format changed")
    return found


def render():
    per_abi = {flag: fetch(abi) for abi, flag in ABIS.items()}
    every = sorted(set().union(*per_abi.values()))
    lines = [HEADER]
    for core in every:
        flags = ",".join(f for f in ("64", "32") if core in per_abi[f])
        lines.append(f"{core} {flags}\n")
    return "".join(lines)


def main():
    generated = render()
    if "--check" in sys.argv:
        current = ASSET.read_text() if ASSET.exists() else ""
        if current != generated:
            sys.exit(f"{ASSET.name} is out of date, re-run scripts/android-cores.py")
        print(f"{ASSET.name} is up to date")
        return
    ASSET.write_text(generated)
    total = len(generated.splitlines()) - len(HEADER.splitlines())
    print(f"wrote {ASSET} with {total} cores")


if __name__ == "__main__":
    main()
